import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_out,
    .param .u32 param_total
)
{
    .reg .pred %p<8>;
    .reg .u32 %r<32>;
    .reg .u64 %rd<16>;
    .reg .f32 %f<16>;

    ld.param.u64 %rd1, [param_in];
    ld.param.u64 %rd2, [param_w];
    ld.param.u64 %rd3, [param_b];
    ld.param.u64 %rd4, [param_out];
    ld.param.u32 %r1, [param_total];

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.u32 %r5, %r2, %r3, %r4;
    setp.ge.u32 %p1, %r5, %r1;
    @%p1 bra DONE;

    rem.u32 %r6, %r5, 55;
    div.u32 %r7, %r5, 55;
    rem.u32 %r8, %r7, 55;
    div.u32 %r9, %r7, 55;
    rem.u32 %r10, %r9, 96;
    div.u32 %r11, %r9, 96;

    mul.lo.u32 %r12, %r11, 150528;
    mul.lo.u32 %r13, %r10, 363;
    shl.b32 %r14, %r8, 2;
    sub.u32 %r14, %r14, 2;
    shl.b32 %r15, %r6, 2;
    sub.u32 %r15, %r15, 2;

    mov.f32 %f1, 0f00000000;

    mov.u32 %r16, 0;
LOOP_C:
    setp.ge.u32 %p2, %r16, 3;
    @%p2 bra END_C;

    mul.lo.u32 %r17, %r16, 50176;
    add.u32 %r17, %r17, %r12;
    mul.lo.u32 %r18, %r16, 121;
    add.u32 %r18, %r18, %r13;

    mov.u32 %r19, 0;
LOOP_KH:
    setp.ge.u32 %p3, %r19, 11;
    @%p3 bra END_KH;

    add.u32 %r20, %r14, %r19;
    setp.ge.u32 %p4, %r20, 224;
    mul.lo.u32 %r21, %r20, 224;
    add.u32 %r21, %r21, %r17;
    mul.lo.u32 %r22, %r19, 11;
    add.u32 %r22, %r22, %r18;

    mov.u32 %r23, 0;
LOOP_KW:
    setp.ge.u32 %p5, %r23, 11;
    @%p5 bra END_KW;

    add.u32 %r24, %r15, %r23;
    setp.ge.u32 %p6, %r24, 224;
    or.pred %p7, %p4, %p6;
    @%p7 bra SKIP;

    add.u32 %r25, %r21, %r24;
    add.u32 %r26, %r22, %r23;
    cvt.u64.u32 %rd5, %r25;
    shl.b64 %rd5, %rd5, 2;
    add.u64 %rd5, %rd5, %rd1;
    cvt.u64.u32 %rd6, %r26;
    shl.b64 %rd6, %rd6, 2;
    add.u64 %rd6, %rd6, %rd2;
    ld.global.f32 %f2, [%rd5];
    ld.global.f32 %f3, [%rd6];
    fma.rn.f32 %f1, %f2, %f3, %f1;

SKIP:
    add.u32 %r23, %r23, 1;
    bra LOOP_KW;
END_KW:
    add.u32 %r19, %r19, 1;
    bra LOOP_KH;
END_KH:
    add.u32 %r16, %r16, 1;
    bra LOOP_C;
END_C:

    cvt.u64.u32 %rd7, %r10;
    shl.b64 %rd7, %rd7, 2;
    add.u64 %rd7, %rd7, %rd3;
    ld.global.f32 %f4, [%rd7];
    add.f32 %f1, %f1, %f4;

    cvt.u64.u32 %rd8, %r5;
    shl.b64 %rd8, %rd8, 2;
    add.u64 %rd8, %rd8, %rd4;
    st.global.f32 [%rd8], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        module = _get_ptx_module()
        n = x.shape[0]
        out = torch.empty((n, 96, 55, 55), dtype=x.dtype, device=x.device)
        total = out.numel()
        module.launch(
            "conv2d_kernel",
            grid=((total + 255) // 256, 1, 1),
            block=(256, 1, 1),
            arguments=[x, self.conv1.weight, self.conv1.bias, out, u32(total)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

